-- gore-dump (generated by gore-cli) — do not edit by hand.
-- Live CDO reader. Writes gore_game_data.json (item stats) and gore_loc_<lang>.json
-- (localized FText names/descriptions for the language the options menu is set
-- to). Triggered by config.lua on launch and/or the `gore-dump` console command.
local CONFIG = require("config")
local STATS_SCHEMA = require("items")
local LOC = require("loc_targets")
local STATS_OUT = "gore_game_data.json"
local INTL_CDO = "/Script/Engine.Default__KismetInternationalizationLibrary"

local function log(msg) print("[gore-dump] " .. tostring(msg) .. "\n") end

local function json_escape(s)
  return (s:gsub('[%z\1-\31\\"]', function(c)
    local map = {['"']='\\"', ['\\']='\\\\', ['\n']='\\n', ['\r']='\\r', ['\t']='\\t'}
    return map[c] or string.format('\\u%04x', string.byte(c))
  end))
end

-- ============================ stats dump ============================

-- Encode a read value as JSON, typed by the field. Returns nil when the value
-- is missing or the wrong Lua type (the field is then emitted without a default).
local function value_json(field_type, v)
  if field_type == "bool" then
    if type(v) == "boolean" then return v and "true" or "false" end
    return nil
  end
  if type(v) ~= "number" then return nil end
  -- JSON has no inf/nan; skip non-finite values so the file stays valid JSON
  -- (the field is then emitted without a default -> GUI shows a placeholder).
  if v ~= v or v == math.huge or v == -math.huge then return nil end
  if field_type == "int" or field_type == "enum" then
    return string.format("%d", math.floor(v + 0.5))
  end
  return string.format("%.17g", v) -- float: round-trips a double
end

local function dump_stats()
  local classes = {}
  for _, cls in ipairs(STATS_SCHEMA) do
    local cdo = StaticFindObject("/Script/Angelscript.Default__" .. cls.id)
    if cdo and cdo:IsValid() then
      local fields = {}
      for _, f in ipairs(cls.fields) do
        local ok, raw = pcall(function() return cdo[f.name] end)
        local parts = {
          string.format('"name":"%s"', json_escape(f.name)),
          string.format('"type":"%s"', json_escape(f.type)),
        }
        if f.enum_values then
          local evs = {}
          for _, e in ipairs(f.enum_values) do
            evs[#evs + 1] = string.format('"%s"', json_escape(e))
          end
          parts[#parts + 1] = '"enum_values":[' .. table.concat(evs, ",") .. ']'
        end
        if f.enum_value_ints then
          local ivs = {}
          for _, n in ipairs(f.enum_value_ints) do
            ivs[#ivs + 1] = string.format("%d", n)
          end
          parts[#parts + 1] = '"enum_value_ints":[' .. table.concat(ivs, ",") .. ']'
        end
        local dj = ok and value_json(f.type, raw) or nil
        if dj then parts[#parts + 1] = '"default":' .. dj end
        fields[#fields + 1] = "{" .. table.concat(parts, ",") .. "}"
      end
      classes[#classes + 1] = string.format(
        '"%s":{"fields":[%s]}', json_escape(cls.id), table.concat(fields, ","))
    else
      log("stats: CDO not found (skipped): " .. cls.id)
    end
  end
  local json = '{"classes":{' .. table.concat(classes, ",") .. '}}'
  local fh = io.open(STATS_OUT, "w")
  if fh then
    fh:write(json); fh:close()
    log("stats: wrote " .. tostring(#classes) .. " classes -> " .. STATS_OUT)
  else
    log("stats: FAILED to open " .. STATS_OUT .. " for writing")
  end
  return #classes
end

-- ============================ loc dump =============================

local function intl() return StaticFindObject(INTL_CDO) end

local function to_str(v)
  if type(v) == "string" then return v end
  if v == nil then return nil end
  local ok, s = pcall(function() return v:ToString() end)
  if ok and type(s) == "string" then return s end
  return nil
end

-- The game's text (Alkimia loc) follows the engine *language*, not the culture
-- (a run showed culture=en-US while text rendered German). Read/write language
-- first; fall back to culture for older builds.
local function current_culture()
  local o = intl(); if not o then return nil end
  for _, fn in ipairs({"GetCurrentLanguage", "GetCurrentCulture"}) do
    local ok, c = pcall(function() return o[fn](o) end)
    if ok then
      local s = to_str(c)
      if s and s ~= "" then return s end
    end
  end
  return nil
end

local function read_ftext(cdo, field)
  local ok, val = pcall(function() return cdo[field] end)
  if not ok then return nil end
  local s = to_str(val)
  if s and s ~= "" then return s end
  return nil
end

-- Filename-safe form of a language label (zh-Hans, pt-BR -> kept; junk dropped).
local function safe_label(lang)
  return (tostring(lang):gsub("[^%w%-_]", ""))
end

-- Dump the localized text the game currently holds, tagged with `lang`. The
-- engine culture/language API does NOT drive the Alkimia loc (verified in-game:
-- culture en-US while text was German), so there is no programmatic switch — the
-- caller sets the language in the game's options menu, then runs this per
-- language. Each call writes gore_loc_<lang>.json; `gore-cli` merges them.
-- NPC CharacterDefinition CDOs only exist once a save is loaded, so run this
-- from inside a loaded game, not the main menu, to capture kind=npc.
local function dump_loc(lang, kinds)
  local label = safe_label(lang)
  if label == "" then
    log("loc: missing language label. Usage: gore-dump loc <lang> [item,npc,knowledge]")
    return 0
  end

  local kindset = {}
  for _, k in ipairs(kinds or {"item", "npc", "knowledge"}) do kindset[k] = true end

  local cur = current_culture()
  log("loc: dumping language '" .. label .. "' (engine reports " .. tostring(cur) .. ")")

  -- NPC names are not baked into the CharacterDefinition CDO (m_Name is empty);
  -- they resolve via the Alkimia loc subsystem keyed by the unique name
  -- (GetText("OC_STT_Diego") -> "Diego"). GetText is the only subsystem call
  -- proven crash-safe in-game (the TArray/TMap getters and the language-set
  -- mutators crash), so we use just that, in the current menu language.
  local locsub = FindFirstOf("AlkimiaLocalizationSubsystem")
  local function loc_get(id)
    if not (locsub and id and id ~= "") then return nil end
    local ok, v = pcall(function() return locsub:GetText(id) end)
    if not ok then return nil end
    local s = to_str(v)
    if s and s ~= "" then return s end
    return nil
  end

  -- per-kind diagnostics: distinguish "CDO not loaded" from "found but no text".
  local total, found, textful = {}, {}, {}

  local parts, n = {}, 0
  for _, t in ipairs(LOC.targets) do
    if kindset[t.kind] then
      total[t.kind] = (total[t.kind] or 0) + 1
      local cdo = StaticFindObject("/Script/Angelscript.Default__" .. t.id)
      if cdo and cdo:IsValid() then
        found[t.kind] = (found[t.kind] or 0) + 1
        local fparts = {}
        if t.kind == "npc" then
          -- name via subsystem(m_UniqueName); description via subsystem too.
          local uid
          local ok, raw = pcall(function() return cdo.m_UniqueName end)
          if ok then uid = to_str(raw) end
          local nm = loc_get(uid)
          if nm then
            fparts[#fparts + 1] = string.format('"m_Name":"%s"', json_escape(nm))
          end
        else
          for _, field in ipairs(LOC.fields_by_kind[t.kind] or {}) do
            local s = read_ftext(cdo, field)
            if s then
              fparts[#fparts + 1] = string.format('"%s":"%s"', json_escape(field), json_escape(s))
            end
          end
        end
        if #fparts > 0 then
          textful[t.kind] = (textful[t.kind] or 0) + 1
          parts[#parts + 1] = string.format('"%s":{"kind":"%s","text":{%s}}',
            json_escape(t.id), json_escape(t.kind), table.concat(fparts, ","))
          n = n + 1
        end
      end
    end
  end

  for _, k in ipairs({"item", "npc", "knowledge"}) do
    if total[k] then
      log(string.format("loc: %s: %d/%d CDOs found, %d with text",
        k, found[k] or 0, total[k], textful[k] or 0))
    end
  end

  local json = string.format('{"language":"%s","entries":{%s}}',
    json_escape(label), table.concat(parts, ","))
  local out_file = "gore_loc_" .. label .. ".json"
  local fh = io.open(out_file, "w")
  if fh then
    fh:write(json); fh:close()
    log("loc: wrote " .. tostring(n) .. " entries -> " .. out_file)
  else
    log("loc: FAILED to open " .. out_file .. " for writing")
  end
  return n
end

-- ====================== console command + auto =====================

-- "all"/empty -> nil (use config default kinds); else split "a,b,c" into a list.
local function parse_csv(s)
  if not s or s == "" or s == "all" then return nil end
  local t = {}
  for w in s:gmatch("[^,]+") do t[#t + 1] = w end
  return t
end

-- Diagnostic: inspect one CDO's candidate name fields. Reports found/empty/value
-- for each, to learn where a kind's display name actually lives.
local PROBE_FIELDS = {
  "m_Name", "m_Description", "m_UniqueName", "m_CharacterName",
  "CharacterName", "m_DisplayName", "Caption", "NameText",
}
local function probe_cdo(class, out)
  if not class or class == "" then
    out("probe: usage: gore-dump probe <ClassName>  (e.g. CharacterDefinition_Human_OC_STT_Diego)")
    return
  end
  local cdo = StaticFindObject("/Script/Angelscript.Default__" .. class)
  if not (cdo and cdo:IsValid()) then
    out("probe: CDO NOT FOUND/loaded: " .. class)
    return
  end
  out("probe: " .. class .. " found. fields:")
  for _, field in ipairs(PROBE_FIELDS) do
    local ok, val = pcall(function() return cdo[field] end)
    if not ok then
      out("  " .. field .. " = <no such field>")
    elseif val == nil then
      out("  " .. field .. " = <nil>")
    else
      local s = to_str(val)
      out("  " .. field .. " = " .. (s == nil and "<not text>" or (s == "" and "<empty>" or '"' .. s .. '"')))
    end
  end
end

-- Probe the Alkimia loc subsystem: language-set names + whether it can read text
-- by id/language directly (which would let one run cover every language).
local function locapi_probe(arg, out)
  local sub = FindFirstOf("AlkimiaLocalizationSubsystem")
  if not (sub and sub:IsValid()) then
    out("locapi: AlkimiaLocalizationSubsystem NOT found")
    return
  end
  out("locapi: subsystem found")

  -- WARNING: pcall does NOT catch native access violations. The TArray/TMap
  -- field iterators and the language-set mutators (SetActiveDisplayLanguageSet /
  -- ReloadLocalization) AV-crash the game, so this probe only uses GetText
  -- (proven safe) and a single FName field read. GetTextAsString is tried only
  -- when you pass an explicit language id: `gore-dump locapi <langId>`.
  local ok, active = pcall(function() return sub.ActiveDisplayLanguageSet end)
  out("  ActiveDisplayLanguageSet = " .. tostring(ok and to_str(active) or "<err>"))

  for _, id in ipairs({"OC_STT_Diego", "OC_STT_Gorn_699"}) do
    local g = pcall(function() return sub:GetText(id) end)
    local v = g and to_str(sub:GetText(id)) or "<err>"
    out("  GetText('" .. id .. "') = " .. tostring(v))
  end

  if arg and arg ~= "" then
    local ok2, v = pcall(function() return sub:GetTextAsString("OC_STT_Diego", arg) end)
    out("  GetTextAsString('OC_STT_Diego','" .. arg .. "') = " .. (ok2 and tostring(to_str(v) or v) or "<err/crash-risk>"))
  end
end

-- gore-dump stats
-- gore-dump loc <lang> [item,npc,knowledge]   (set the menu language first)
-- gore-dump all <lang> [item,npc,knowledge]
-- gore-dump probe <ClassName>                 (inspect one CDO's name fields)
-- gore-dump locapi [langSet]                  (probe the Alkimia loc subsystem)
RegisterConsoleCommandHandler("gore-dump", function(_, Parameters, Ar)
  local function out(m)
    if Ar then pcall(function() Ar:Log(m) end) end
    log(m)
  end
  local sub = string.lower(Parameters[1] or "")
  if sub == "stats" then
    out("stats: wrote " .. tostring(dump_stats()) .. " classes")
  elseif sub == "loc" then
    local kinds = parse_csv(Parameters[3]) or CONFIG.loc.kinds
    out("loc: wrote " .. tostring(dump_loc(Parameters[2], kinds)) .. " entries")
  elseif sub == "all" then
    dump_stats()
    local kinds = parse_csv(Parameters[3]) or CONFIG.loc.kinds
    dump_loc(Parameters[2], kinds)
    out("all: done")
  elseif sub == "probe" then
    probe_cdo(Parameters[2], out)
  elseif sub == "locapi" then
    locapi_probe(Parameters[2], out)
  else
    out("usage: gore-dump <stats | loc <lang> | all <lang> | probe <Class> | locapi [set]> [item,npc,knowledge]")
  end
  return true
end)

do
  local o = intl()
  if o then
    local function try(fn)
      local ok, v = pcall(function() return o[fn](o) end)
      return ok and to_str(v) or "?"
    end
    -- Diagnostic only: the engine language/culture does NOT drive the Alkimia
    -- loc, so this is just FYI — the dumped text follows the options-menu language.
    log("engine language = " .. try("GetCurrentLanguage") .. ", culture = " .. try("GetCurrentCulture"))
  end
end

if CONFIG.auto and CONFIG.auto.enabled and CONFIG.auto.stats then
  log("loaded; auto stats-dump in " .. tostring(CONFIG.auto.delay_ms)
    .. "ms. Loc: set the menu language, then `gore-dump loc <lang>` (from a loaded save for NPCs).")
  ExecuteWithDelay(CONFIG.auto.delay_ms, function() dump_stats() end)
else
  log("loaded. Loc: set the menu language, then `gore-dump loc <lang>` (from a loaded save for NPCs).")
end
